head.script:
scwin.onpageload = function () {
    // 세션 정보 담을 공간
    scwin.sessionData = {};

    // 초대 링크와 만료일을 미리 생성해서 저장
    scwin.sessionData.generatedInfo = {
        inviteLink: null,
        linkExpiry: null // 세션 종료시간에서 6시간후 만료시간
    };

    scwin.step1_onclick();
};

// 종료시간 기준으로 만료일 계산 함수
scwin.calculateExpiry = function (endTime) {
    if (!endTime) {
        return null;
    }

    var endDate;

    // YYYYMMDDHHMM 형식 처리
    if (typeof endTime === 'string' && endTime.length === 12) {
        var year = endTime.substring(0, 4);
        var month = endTime.substring(4, 6);
        var day = endTime.substring(6, 8);
        var hour = endTime.substring(8, 10);
        var minute = endTime.substring(10, 12);

        // ISO 형식으로 변환
        var isoString = year + '-' + month + '-' + day + 'T' + hour + ':' + minute + ':00';
        endDate = new Date(isoString);
    } else {
        // 다른 형식은 기본 변환 시도
        endDate = new Date(endTime);
    }

    if (isNaN(endDate.getTime())) {
        return null;
    }

    // 종료시간에서 6시간 추가
    var expiry = new Date(endDate.getTime() + 6 * 60 * 60 * 1000);

    var result = expiry.getFullYear() + '-' +
        String(expiry.getMonth() + 1).padStart(2, '0') + '-' +
        String(expiry.getDate()).padStart(2, '0') + ' ' +
        String(expiry.getHours()).padStart(2, '0') + ':' +
        String(expiry.getMinutes()).padStart(2, '0') + ':' +
        String(expiry.getSeconds()).padStart(2, '0');

    return result;
};

scwin.setScreen = function (idx) {

    if (idx == 1) {
        step1.addClass("on");
        step2.removeClass("on");
        step3.removeClass("on");
        step4.removeClass("on");
        fr_session_making_process.setSrc("/InsWebApp/main/session_process/session_info_input.xml");
    } else if (idx == 2) {
        step1.removeClass("on");
        step2.addClass("on");
        step3.removeClass("on");
        step4.removeClass("on");
        fr_session_making_process.setSrc("/InsWebApp/main/session_process/layout-designer.xml");
    } else if (idx == 3) {
        step1.removeClass("on");
        step2.removeClass("on");
        step3.addClass("on");
        step4.removeClass("on");
        fr_session_making_process.setSrc("/InsWebApp/main/session_process/session_invitation.xml");
    } else if (idx == 4) {
        step1.removeClass("on");
        step2.removeClass("on");
        step3.removeClass("on");
        step4.addClass("on");
        fr_session_making_process.setSrc("/InsWebApp/main/session_process/make_session_complete.xml");
    }
};

// progress 클릭
scwin.step1_onclick = function (e) {
    scwin.setScreen(1);
};

scwin.step2_onclick = function (e) {
    scwin.setScreen(2);
};

scwin.step3_onclick = function (e) {
    scwin.setScreen(3);
};

scwin.step4_onclick = function (e) {
    scwin.setScreen(4);
};

// 1단계에서 넘겨받은 데이터 저장 함수
scwin.setSessionInfo = function (data) {
    scwin.sessionData.sessionInfo = data;
    // 종료시간 기준으로 링크 만료시간 계산
    var linkExpiry = scwin.calculateExpiry(data.end_time);
    scwin.sessionData.generatedInfo.linkExpiry = linkExpiry;
}

// 2단계에서 넘겨받은 데이터 저장 함수
scwin.setLayoutConfig = function (layoutData) {
    scwin.sessionData.layoutConfig = layoutData;
}

// 3단계에서 넘겨받은 데이터 저장 함수
scwin.setInviteInfo = function (inviteData) {
    scwin.sessionData.inviteInfo = inviteData;
};

scwin.navigateToLayout = function (sessionId) {
    console.log("새 창으로 세션 페이지 열기. Session ID:", sessionId);

    if (!sessionId) {
        alert("세션 ID가 없습니다.");
        return;
    }

    try {
        localStorage.setItem('currentSessionId', sessionId);

        // 새 창 URL 구성
        var sessionUrl = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/session_room/session_room3.xml";

        // 새 창 열기
        var popup = window.open(
            sessionUrl,
            "sessionRoom_" + sessionId,
            "width=1200,height=800,scrollbars=yes,resizable=yes,menubar=no,toolbar=no"
        );

        if (popup) {
            popup.focus(); // 새 창에 포커스
            console.log("새 창 열기 성공");
        } else {
            throw new Error("팝업이 차단되었습니다.");
        }

    } catch (error) {
        console.error("새 창 열기 실패:", error);
        alert("팝업 차단으로 인해 새 창을 열 수 없습니다.\n브라우저 설정에서 팝업을 허용해주세요.");
    }
};

scwin.saveAllSessionData = function (callback) {
    try {
        var startTimeRaw = scwin.sessionData.sessionInfo.start_time;
        var endTimeRaw = scwin.sessionData.sessionInfo.end_time;
        // inviteLink는 제외 - null이나 빈 문자열 대신 아예 설정하지 않음
        var linkExpiry = scwin.sessionData.generatedInfo.linkExpiry;

        function formatDateTime(dateTimeStr) {
            if (!dateTimeStr || dateTimeStr.length !== 12) {
                return dateTimeStr;
            }
            var year = dateTimeStr.substring(0, 4);
            var month = dateTimeStr.substring(4, 6);
            var day = dateTimeStr.substring(6, 8);
            var hour = dateTimeStr.substring(8, 10);
            var minute = dateTimeStr.substring(10, 12);
            return year + '-' + month + '-' + day + ' ' + hour + ':' + minute + ':00';
        }

        var startTime = formatDateTime(startTimeRaw);
        var endTime = formatDateTime(endTimeRaw);

        dma_sessionData.set("name", scwin.sessionData.sessionInfo.name);
        dma_sessionData.set("usingDept", scwin.sessionData.sessionInfo.using_dept);
        dma_sessionData.set("startTime", startTime);
        dma_sessionData.set("endTime", endTime);
        dma_sessionData.set("inviteLink", null);
        dma_sessionData.set("linkExpiry", linkExpiry);
        dma_sessionData.set("createdBy", "1");

        scwin.completionCallback = callback;
        $p.executeSubmission("sbm_createSession");

    } catch (error) {
        console.error("저장 중 오류:", error);
        alert("저장 중 오류가 발생했습니다: " + error.message);
    }
};

scwin.sbm_createSession_submitdone = function (e) {
    console.log("세션 생성 성공");

    var sessionId = null;

    try {
        if (e.responseJSON) {
            sessionId = e.responseJSON.sessionId || e.responseJSON.id || e.responseJSON.session_id;
        }

        if (!sessionId && e.responseText) {
            var responseData = JSON.parse(e.responseText);
            sessionId = responseData.sessionId || responseData.id || responseData.session_id;
        }

        if (!sessionId && e.result) {
            sessionId = e.result.sessionId || e.result.id || e.result.session_id;
        }

        if (!sessionId) {
            alert("세션 ID를 받지 못했습니다. 서버 응답을 확인해주세요.");
            return;
        }

        if (sessionId) {
            // sessionId를 받은 후에 초대링크 생성 -> 트러블 슈팅
            scwin.sessionData.generatedInfo.inviteLink =
               //"https://unify-conference.store/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/ui/session_room/session_room3.xml&sessionId=" + sessionId;
                "https://localhost:19443/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/ui/session_room/session_room3.xml&sessionId=" + sessionId;

            console.log("inviteLink:", scwin.sessionData.generatedInfo.inviteLink);
            scwin.currentSessionId = sessionId;

            // 초대링크 업데이트 먼저 실행
            scwin.updateInviteLink(sessionId, scwin.sessionData.generatedInfo.inviteLink);
        }

    } catch (error) {
        console.error("sessionId 추출 오류:", error);
        alert("세션 ID 추출 중 오류가 발생했습니다: " + error.message);
    }
};

// 초대링크 업데이트 함수
scwin.updateInviteLink = function(sessionId, inviteLink) {
    dma_updateInviteLink.set("sessionId", sessionId);
    dma_updateInviteLink.set("inviteLink", inviteLink);

    $p.executeSubmission("sbm_updateInviteLink");
};

// 모듈 저장 함수
scwin.saveSessionModules = function (sessionId) {
    dlt_sessionModules.removeAll();
    var layoutConfig = scwin.sessionData.layoutConfig;

    if (!layoutConfig || layoutConfig.length === 0) {
        alert("세션이 생성되었지만 배치된 모듈이 없습니다.");
        return;
    }

    layoutConfig.forEach(function (item, index) {
        var rowIndex = dlt_sessionModules.insertRow();
        dlt_sessionModules.setCellData(rowIndex, "sessionId", sessionId.toString());
        dlt_sessionModules.setCellData(rowIndex, "moduleId", item.moduleId.toString());
        dlt_sessionModules.setCellData(rowIndex, "sessionModuleConfig", item.sessionModuleConfig);
    });

    scwin.currentSessionId = sessionId;
    $p.executeSubmission("sbm_createSessionModules");
};

scwin.sbm_createSessionModules_submitdone = function (e) {
    var sessionId = scwin.currentSessionId;

    // 팝업에 전달할 데이터 객체 생성
    var popupData = {
        sessionId: sessionId,
        sessionName: scwin.sessionData.sessionInfo ? scwin.sessionData.sessionInfo.name : "새 세션",
        inviteLink: scwin.sessionData.generatedInfo ? scwin.sessionData.generatedInfo.inviteLink : "초대링크 생성 중..."
    };

    console.log("팝업에 전달할 데이터:", popupData);

    // 방법 1: 기존 createPopUp 함수 사용
    try {
        scwin.createPopUp(
            "sessionCompletePopUp",
            "세션 생성 완료", 
            popupData,
            "/InsWebApp/ui/popup/session_complete_popup.xml",
            700,
            700
        );
    } catch (error) {
        console.error("createPopUp 함수 실패:", error);

        // 방법 2: 직접 $p.openPopup 사용
        try {
            var options = {
                width: "700px",
                height: "700px",
                modal: true,
                popupName: "세션 생성 완료",
                closeAction: "scwin.popup_closeAction",
                dataObject: popupData
            };

            $p.openPopup("/InsWebApp/ui/popup/session_complete_popup.xml", options, popupData);
        } catch (error2) {
            console.error("직접 팝업 호출도 실패:", error2);
            alert("팝업을 열 수 없습니다. 세션은 생성되었습니다.\nSession ID: " + sessionId);
        }
    }
};

scwin.sbm_createSessionModules_submiterror = function (e) {
    alert('모듈 배치 정보 저장 실패');
};

// 초대링크 업데이트 함수
scwin.updateInviteLink = function(sessionId, inviteLink) {
    dma_updateInviteLink.set("sessionId", sessionId);
    dma_updateInviteLink.set("inviteLink", inviteLink);

    $p.executeSubmission("sbm_updateInviteLink");
};

// 초대링크 업데이트 완료 후 모듈 저장 진행
scwin.sbm_updateInviteLink_submitdone = function(e) {
    console.log("초대링크 업데이트 완료");

    // 이제 모듈 저장 진행
    scwin.saveSessionModules(scwin.currentSessionId);
};

scwin.sbm_updateInviteLink_submiterror = function(e) {
    console.error("초대링크 업데이트 실패:", e);
    alert("초대링크 업데이트에 실패했습니다.");

    // 실패해도 모듈 저장은 진행할지 결정
    if (confirm("초대링크 업데이트에 실패했지만 모듈 저장을 계속 진행하시겠습니까?")) {
        scwin.saveSessionModules(scwin.currentSessionId);
    }
};

scwin.createPopUp = function (_id, _name, _jsnData, url, _popupWidth, _popupHeight) {
    console.log("=== createPopUp 함수 호출 ===");
    console.log("팝업 ID:", _id);
    console.log("팝업 이름:", _name);
    console.log("전달 데이터:", _jsnData);
    console.log("팝업 URL:", url);

    if ($p.getPopup(_id)) {
        console.log(`Popup with ID '${_id}' already exists. Skipping creation.`);
        return;
    }

    var popupWidth = _popupWidth;
    var popupHeight = _popupHeight;
    var topPosition = (window.innerHeight - popupHeight) / 2;
    var leftPosition = (window.innerWidth - popupWidth) / 2;

    var options = {
        id: _id,
        type: "wframePopup",
        width: popupWidth + "px",
        height: popupHeight + "px",
        top: topPosition + "px",
        left: leftPosition + "px",
        popupName: _name,
        modal: true,
        closeAction: "scwin.popup_closeAction",  // 이 부분이 중요!
        dataObject: _jsnData
    };

    console.log("팝업 옵션:", options);
    console.log("closeAction 설정:", options.closeAction);

    // 팝업 열기 전에 closeAction 함수가 존재하는지 확인
    if (typeof scwin.popup_closeAction === 'function') {
        console.log("popup_closeAction 함수 존재함");
    } else {
        console.error("popup_closeAction 함수가 존재하지 않음!");
    }

    $p.openPopup(url, options);
    console.log("팝업 열기 완료");
}

// 팝업 닫기 액션
scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    console.log("=== 팝업 닫기 액션 호출됨 ===");
    console.log("argRuntimeID:", argRuntimeID);
    console.log("argJsnInfo:", argJsnInfo);
    console.log("argJsnInfo 타입:", typeof argJsnInfo);

    try {
        // 팝업에서 반환된 결과 데이터 확인
        if (argJsnInfo) {
            console.log("argJsnInfo.action:", argJsnInfo.action);
            console.log("argJsnInfo.confirmed:", argJsnInfo.confirmed);
            console.log("argJsnInfo.sessionId:", argJsnInfo.sessionId);

            if (argJsnInfo.action === "start" && argJsnInfo.confirmed) {
                console.log("=== 세션 시작 조건 만족 ===");

                // "세션 시작하기" 버튼을 눌렀을 때
                var sessionId = argJsnInfo.sessionId || scwin.currentSessionId;
                console.log("최종 sessionId:", sessionId);
                console.log("scwin.currentSessionId:", scwin.currentSessionId);

                if (sessionId) {
                    console.log("세션 시작으로 페이지 이동:", sessionId);

                    // localStorage에 sessionId 저장 (세션 페이지에서 사용)
                    try {
                        localStorage.setItem('currentSessionId', sessionId);
                        console.log("localStorage에 sessionId 저장 완료:", sessionId);
                    } catch (e) {
                        console.warn("localStorage 저장 실패:", e);
                    }

                    // 세션 페이지로 이동
                    console.log("navigateToLayout 함수 호출 시작");
                    scwin.navigateToLayout(sessionId);

                } else {
                    console.error("sessionId가 없어서 페이지 이동할 수 없습니다.");
                    alert("세션 ID를 찾을 수 없습니다. 다시 시도해주세요.");
                }

            } else {
                console.log("=== 세션 시작 조건 불만족 ===");
                console.log("action === 'start':", argJsnInfo.action === "start");
                console.log("confirmed:", argJsnInfo.confirmed);
            }
        } else {
            console.log("=== argJsnInfo가 null/undefined ===");
        }

        // "나중에 시작" 버튼을 눌렀거나 팝업을 닫았을 때
        if (!argJsnInfo || argJsnInfo.action !== "start") {
            console.log("팝업이 닫혔습니다. 추가 동작 없음.");
        }

    } catch (error) {
        console.error("팝업 닫기 처리 중 오류:", error);
        alert("페이지 이동 중 오류가 발생했습니다: " + error.message);
    }

    console.log("=== popup_closeAction 함수 종료 ===");
    return true; // 팝업 닫기
};
